package com.edgedirect2u.shell;
import org.junit.Test;
import static org.junit.Assert.*;
public class NavigationPolicyTest {
    @Test public void authenticatedExportsRequireTheSameTrustedOrigin(){assertTrue(NavigationPolicy.download("https://edgedirect2u.com/api/admin/export?kind=products","https://edgedirect2u.com/admin/products"));assertFalse(NavigationPolicy.download("https://edgedirect2u.vercel.app/api/admin/export","https://edgedirect2u.com/admin"));assertFalse(NavigationPolicy.download("https://evil.test/export","https://edgedirect2u.com/admin"));assertFalse(NavigationPolicy.download("http://edgedirect2u.com/export","https://edgedirect2u.com/admin"));assertFalse(NavigationPolicy.download("https://edgedirect2u.com:8443/export","https://edgedirect2u.com/admin"));assertFalse(NavigationPolicy.download("https://edgedirect2u.com/export","https://evil.test/"));}
    @Test public void locationRequiresDriverFieldPageAndMatchingTrustedOrigin(){assertTrue(NavigationPolicy.location("https://edgedirect2u.com/","https://edgedirect2u.com/field/e-edge-direct-2u",true));assertFalse(NavigationPolicy.location("https://edgedirect2u.com/","https://edgedirect2u.com/field/e-edge-direct-2u",false));assertFalse(NavigationPolicy.location("https://evil.test/","https://edgedirect2u.com/field/e-edge-direct-2u",true));assertFalse(NavigationPolicy.location("https://edgedirect2u.com/","https://edgedirect2u.com/login",true));assertFalse(NavigationPolicy.location("https://edgedirect2u.vercel.app/","https://edgedirect2u.com/field/e-edge-direct-2u",true));assertFalse(NavigationPolicy.location("https://edgedirect2u.com/?tracking=1","https://edgedirect2u.com/field/e-edge-direct-2u",true));}
    @Test public void hostedStoreIsTrustedWithoutAcceptingOtherVercelTenants(){assertTrue(NavigationPolicy.internal(NavigationPolicy.HOME+"/login"));assertFalse(NavigationPolicy.internal("https://edgedirect2u.vercel.app.evil.test/"));assertFalse(NavigationPolicy.internal("https://another-store.vercel.app/"));assertFalse(NavigationPolicy.internal("https://edgedirect2u.vercel.app@evil.test/"));assertTrue(NavigationPolicy.appLink(NavigationPolicy.HOME+"/checkout/confirmation?reference=abc","/"));}
    @Test public void internalNavigationRequiresExactSecureOrigin(){assertTrue(NavigationPolicy.internal("https://edgedirect2u.com/account"));assertFalse(NavigationPolicy.internal("http://edgedirect2u.com/"));assertFalse(NavigationPolicy.internal("https://edgedirect2u.com.evil.test/"));assertFalse(NavigationPolicy.internal("https://edgedirect2u.com@evil.test/"));assertFalse(NavigationPolicy.internal("https://edgedirect2u.com:8443/"));assertFalse(NavigationPolicy.internal("javascript:alert(1)"));assertFalse(NavigationPolicy.internal(null));}
    @Test public void externalNavigationRequiresGestureOrTrustedPayment(){assertTrue(NavigationPolicy.external("https://checkout.paystack.com/session",false));assertTrue(NavigationPolicy.external("https://maps.google.com/",true));assertFalse(NavigationPolicy.external("https://evil.test/",false));assertFalse(NavigationPolicy.external("intent://evil",true));assertFalse(NavigationPolicy.external("file:///private",true));assertFalse(NavigationPolicy.external("https://user:pass@evil.test/",true));}
    @Test public void deepLinksCannotOpenArbitraryScreens(){assertTrue(NavigationPolicy.appLink("https://edgedirect2u.com/checkout/confirmation?reference=abc","/"));assertFalse(NavigationPolicy.appLink("https://edgedirect2u.com/admin","/"));assertTrue(NavigationPolicy.appLink("https://edgedirect2u.com/driver","/driver"));assertFalse(NavigationPolicy.appLink("https://edgedirect2u.com/driver-evil","/driver"));assertFalse(NavigationPolicy.appLink("https://evil.test/driver","/driver"));}
}
